static const char EXPECTED_PAYLOAD[] = "wolfCOSE HSS-LMS benchmark payload";

int main(void)
{
    LmsKey         lmsKey;
    WOLFCOSE_KEY   key;
    WOLFCOSE_HDR   hdr;
    unsigned char  scratch[4096];
    const uint8_t* payload = NULL;
    size_t         payloadLen = 0;
    int            ret;
    int            rc = 1;

    if (wc_LmsKey_Init(&lmsKey, NULL, INVALID_DEVID) != 0) {
        (void)printf("wc_LmsKey_Init failed\n");
        return 1;
    }

    /* Import the public key only; the RFC 8554 type codes inside it select
     * the LMS parameter set. */
    ret = wc_LmsKey_ImportPubRaw(&lmsKey, LMS_PUB, (word32)sizeof(LMS_PUB));
    if (ret == 0) {
        ret = wc_CoseKey_Init(&key);
    }
    if (ret == 0) {
        ret = wc_CoseKey_SetLms(&key, &lmsKey);
    }
    if (ret == 0) {
        (void)memset(&hdr, 0, sizeof(hdr));
        ret = wc_CoseSign1_Verify(&key, LMS_COSE, sizeof(LMS_COSE),
                                  NULL, 0, NULL, 0,
                                  scratch, sizeof(scratch), &hdr,
                                  &payload, &payloadLen);
    }

    if ((ret == WOLFCOSE_SUCCESS) &&
        (payloadLen == (sizeof(EXPECTED_PAYLOAD) - 1)) &&
        (payload != NULL) &&
        (memcmp(payload, EXPECTED_PAYLOAD, payloadLen) == 0)) {
        (void)printf("lean HSS-LMS verify-only: COSE_Sign1 verified, "
                     "payload = \"%.*s\"\n", (int)payloadLen, payload);
        rc = 0;
    }
    else if (ret == WOLFCOSE_SUCCESS) {
        (void)printf("lean HSS-LMS verify-only: payload mismatch\n");
    }
    else {
        (void)printf("lean HSS-LMS verify-only: verify failed (%d)\n", ret);
    }

    wc_CoseKey_Free(&key);
    wc_LmsKey_Free(&lmsKey);
    return rc;
}
